import { loadCrapsProducer } from './replay-producer.js';
import { keccak256, AbiCoder } from '../vendor/ethers-app.mjs';

/** The contract hashes the combined walk ordinal, including day and awarded seats. */
export function crapsReplayFinalRankings(entries, word, boundSlot, scoreOf) {
  const coder = AbiCoder.defaultAbiCoder();
  const ranked = entries.map((entry, index) => ({
    betId: String(entry.betId),
    high: entry.multiple > 1,
    score: scoreOf(entry.result),
    tie: BigInt(keccak256(coder.encode(['uint256', 'uint256', 'uint256'], [
      word, 0x4372617073546965n, (BigInt(boundSlot) << 64n) | BigInt(index + 1),
    ]))),
  })).sort((a, b) => a.score !== b.score ? (a.score > b.score ? -1 : 1)
    : a.tie === b.tie ? 0 : a.tie > b.tie ? -1 : 1);
  return { main: ranked.map(entry => entry.betId), high: ranked.filter(entry => entry.high).map(entry => entry.betId) };
}

export async function materializeReplay(input) {
  const { replayField, buildCrapsReplayBundle, rankOf } = await loadCrapsProducer(input.ruleset?.engineVersion);
  const { tape, entries } = replayField({ ...input.terms, boundSlot: input.settlement.boundSlot, word: input.word, entrants: input.seats.length,
    ...(input.rollBudget != null ? { rollBudget: BigInt(input.rollBudget) } : {}) }, input.seats);
  const bundle = buildCrapsReplayBundle({ ...input, tape: { ...tape, maxHands: tape.offsets.length / 4 }, seats: entries.map((entry, i) => ({ entry, lane: input.seats[i].lane, chainWon: input.seats[i].chainWon, chainPaid: input.seats[i].chainPaid })) });
  const rankings = crapsReplayFinalRankings(entries, input.word, input.settlement.boundSlot, rankOf);
  if (input.winnerSeat > 0 && rankings.main[0] !== String(entries[Number(input.winnerSeat) - 1]?.betId)) {
    throw new Error('Replayed final rank disagrees with the settled battle winner.');
  }
  return { ...bundle, rankings };
}
if (typeof self !== 'undefined' && typeof document === 'undefined') self.onmessage = async ({ data }) => {
  try {
    const bundle = await materializeReplay(data);
    self.postMessage({ digest: bundle.digest, pointerPath: bundle.pointerPath, entrants: bundle.entrants, rankings: bundle.rankings,
      files: [...bundle.children, bundle.manifest].map(child => ({ path: child.path, body: child.body.toString('utf8') })) });
  } catch (error) { self.postMessage({ error: error.message }); }
};
